func conversionSeed(oid ids.OID) *conversionDescriptor {
	if oid < 4402 || oid > 4531 || oid == 4450 || oid == 4451 {
		return nil
	}
	index := int(oid - 4402)
	if oid >= 4452 {
		index -= 2
	}
	return &builtinConversions[index]
}

func (d *conversionDescriptor) seeded() bool { return conversionSeed(d.OID) != nil }
